import { describe, expect, it, vi } from "vitest";

// dist/wasm/movi.js is generated by build:wasm (Docker/4090) and is absent in
// the unit-test CI job (dist/ is gitignored). Demuxer's module graph imports it
// eagerly via FFmpegLoader; this test never loads/runs the WASM, so stub the
// module so importing Demuxer resolves without the built artifact.
//
// The bindings double below stands in for that same unreachable WASM module —
// it is the dependency, not the logic under test. What is under test is
// Demuxer's own serialization, and it genuinely runs here: the double reports
// how many calls are inside the module at once, which is the whole invariant.
// The behavioural half of this contract is covered against the real WASM by the
// OpenList black-box (a seek issued while the element's poster seek(0) is still
// suspended used to leave the demuxer reading from the old position forever).
vi.mock("../../dist/wasm/movi.js", () => ({ default: vi.fn(async () => ({})) }));

import { Demuxer } from "../../src/demux/Demuxer";

type Deferred = { promise: Promise<void>; resolve: () => void };

function deferred(): Deferred {
  let resolve!: () => void;
  const promise = new Promise<void>((r) => {
    resolve = r;
  });
  return { promise, resolve };
}

/**
 * A Demuxer wired to a bindings double that records module concurrency: how many
 * calls are inside it right now, and the high-water mark across the test.
 */
function createDemuxerWithGates() {
  const gates: Deferred[] = [];
  const state = { inside: 0, maxInside: 0, order: [] as string[] };

  const enter = async (label: string) => {
    state.inside++;
    state.maxInside = Math.max(state.maxInside, state.inside);
    state.order.push(label);
    const gate = deferred();
    gates.push(gate);
    await gate.promise;
    state.inside--;
  };

  // A real instance: the constructor is what initialises the serialization
  // field, and it only stores its arguments, so the source is never touched.
  const demuxer = new Demuxer({} as never) as Demuxer & {
    bindings: unknown;
    isOpened: boolean;
  };
  demuxer.bindings = {
    seek: vi.fn(async (timestamp: number) => {
      await enter(`seek:${timestamp}`);
    }),
    readFrame: vi.fn(async () => {
      await enter("read");
      return null;
    }),
  };
  demuxer.isOpened = true;

  return { demuxer, gates, state };
}

/** Let queued microtasks run so a chained call reaches the binding. */
const settle = () => new Promise((r) => setTimeout(r, 0));

describe("Demuxer serializes WASM entry points", () => {
  it("does not start a second seek while the first is still inside the module", async () => {
    const { demuxer, gates, state } = createDemuxerWithGates();

    const first = demuxer.seek(0, 1, 0);
    await settle();
    const second = demuxer.seek(1377.568, 1, 0);
    await settle();

    // The poster seek is still suspended; the user seek must not be inside too.
    expect(state.inside).toBe(1);
    expect(state.order).toEqual(["seek:0"]);

    gates[0].resolve();
    await first;
    await settle();

    expect(state.order).toEqual(["seek:0", "seek:1377.568"]);
    gates[1].resolve();
    await second;

    expect(state.maxInside).toBe(1);
  });

  it("does not start a read while a seek is still inside the module", async () => {
    const { demuxer, gates, state } = createDemuxerWithGates();

    const seek = demuxer.seek(1377.568, 1, 0);
    await settle();
    const read = demuxer.readPacket();
    await settle();

    expect(state.inside).toBe(1);
    expect(state.order).toEqual(["seek:1377.568"]);

    gates[0].resolve();
    await seek;
    await settle();

    expect(state.order).toEqual(["seek:1377.568", "read"]);
    gates[1].resolve();
    await read;

    expect(state.maxInside).toBe(1);
  });

  it("keeps serving later callers after one entry point rejects", async () => {
    const { demuxer, gates, state } = createDemuxerWithGates();
    (demuxer.bindings as { seek: unknown }).seek = vi.fn(async () => {
      throw new Error("Seek failed: error -22");
    });

    await expect(demuxer.seek(500, 1, 0)).rejects.toThrow("Seek failed");

    const read = demuxer.readPacket();
    await settle();
    expect(state.order).toEqual(["read"]);
    gates[0].resolve();
    await expect(read).resolves.toBeNull();
  });
});
